import { formatUser } from "../server";
import { renderProfile } from "../client";

describe("formatUser", () => {
  it("maps raw DB fields to API response fields", () => {
    const raw = { id: "1", firstName: "Alice", lastName: "Smith", emailAddress: "a@b" };
    expect(formatUser(raw)).toEqual({ id: "1", first: "Alice", last: "Smith", email: "a@b" });
  });
});

describe("renderProfile", () => {
  it("renders a formatted UserResponse", () => {
    const response = formatUser({ id: "1", firstName: "A", lastName: "B", emailAddress: "a@b" });
    expect(renderProfile(response)).toBe("# A B\na@b");
  });
});

